	private static Stream<Arguments> pathVariants() {
		Stream.Builder<Arguments> result = Stream.builder();
		for (Endpoint endpoint : Endpoint.values()) {
			for (int selected : new int[] { 0, 1, 2 }) {
				for (int unrelated : new int[] { 1, 2, 4 }) {
					result.add(Arguments.of(endpoint, 0L, false, selected, unrelated));
					result.add(Arguments.of(endpoint, 1L, false, selected, unrelated));
					result.add(Arguments.of(endpoint, 0L, true, selected, unrelated));
				}
			}
		}
		return result.build();
	}

	private static FilteredFactor filteredPath(Endpoint endpoint, long minimum, boolean zeroLength,
			int selected, int unrelated) {
		List<String> names = endpoint == Endpoint.BOTH ? List.of("s", "o")
				: endpoint == Endpoint.START ? List.of("s") : List.of("o");
		List<BindingSet> rows = new ArrayList<>();
		for (int branch = 0; branch < 4; branch++) {
			Value[] values = endpoint == Endpoint.BOTH ? new Value[] { start(branch), end(branch) }
					: new Value[] { endpoint == Endpoint.START ? start(branch) : end(branch) };
			for (int occurrence = 0; occurrence < unrelated; occurrence++) {
				rows.add(new ListBindingSet(names, values));
			}
		}
		BindingSetAssignment assignment = assignment(names, rows);
		String selectedName = names.getFirst();
		ValueExpr condition = new Compare(Var.of(selectedName), new ValueConstant(VF.createIRI("urn:absent")),
				Compare.CompareOp.EQ);
		for (int branch = 0; branch < selected; branch++) {
			condition = new Or(condition, new Compare(Var.of(selectedName),
					new ValueConstant(endpoint == Endpoint.END ? end(branch) : start(branch)), Compare.CompareOp.EQ));
		}
		Filter prefix = new Filter(assignment, condition);
		TupleExpr factor = zeroLength ? new ZeroLengthPath(Var.of("s"), Var.of("o"))
				: new ArbitraryLengthPath(Var.of("s"), pattern("s", STEP, "o"), Var.of("o"), minimum);
		Join expression = new Join(prefix, factor);
		return new FilteredFactor(expression, prefix, factor, Set.copyOf(names));
	}

	static void assertNativeRows(JoinFactorCostModel.FactorCostEstimate producer, PackedCostEstimate output,
			String context) {
		assertEquals(producer.getOutputRows(), output.outputRows(), 0.0d,
				context + ": logical ROW must come from the actual native semantic producer");
		assertTrue(output.hasContextualOutputRows(), context + ": producer rows already cover actual R");
		assertFalse(output.hasComponentOutputRows(), context + ": native scalar rows already include U");
	}

	static void assertBindingOnly(PackedCostEstimate output) {
		assertTrue(output.evidenceStateId() > 0, "same-session binding-only continuation must remain available");
		assertEquals(0.0d, output.plannedDoubleMetric("plannedFrontierFactorCount", Double.NaN), 0.0d,
				"binding authority has no statistical factor inventory");
		assertEquals(EvidenceGuarantee.SCALAR_FALLBACK, output.evidenceGuarantee());
		assertEquals(FrontierStateDisposition.BOUND_ONLY, output.evidenceDisposition());
		assertFalse(output.runtimeFeedbackContract() != null
				&& output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
		assertFalse(output.runtimeFeedbackContract() != null
				&& output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
	}

	private static void assertPathPhysicalQuantities(TupleExpr factor,
			JoinFactorCostModel.FactorCostEstimate producer, PackedCostEstimate output) {
		double invocations = producer.getDoubleMetrics().get("plannedRepeatedInvocations");
		assertEquals(invocations, output.invocations(), 0.0d);
		if (factor instanceof ArbitraryLengthPath) {
			Map<String, Double> quantities = producer.getDoubleMetrics();
			if (invocations == 0.0d) {
				// The native no-executions producer returns a scalar zero before path expansion metrics exist.
				assertEquals(0.0d, producer.getOutputRows(), 0.0d);
				assertEquals(0.0d, producer.getWorkRows(), 0.0d);
				assertEquals(0.0d, quantities.get("plannedSeeks"), 0.0d);
				assertFalse(quantities.containsKey(LmdbPropertyPathEstimator.PLANNED_PATH_CANDIDATE_ROWS));
				assertFalse(quantities.containsKey(LmdbPropertyPathEstimator.PLANNED_PATH_STEP_LOOKUPS));
				assertFalse(quantities.containsKey(LmdbPropertyPathEstimator.PLANNED_PATH_EXPANSION_ITERATIONS));
				assertEquals(0.0d, output.workRows(), 0.0d);
				assertEquals(0.0d, output.sequentialRows(), 0.0d);
				assertEquals(0.0d, output.randomSeeks(), 0.0d);
				assertEquals(0.0d, output.iteratorOpens(), 0.0d);
				assertEquals(0.0d, output.expressionEvaluations(), 0.0d);
				assertEquals(0.0d, output.hashBuildRows(), 0.0d);
				assertEquals(0.0d, output.hashProbeRows(), 0.0d);
				assertEquals(0.0d, output.pathExpansions(), 0.0d);
				assertEquals(0.0d, output.resultRows(), 0.0d);
				assertEquals(0.0d, output.remoteCalls(), 0.0d);
				assertEquals(0.0d, output.peakMemoryRows(), 0.0d);
				return;
			}
			assertNotNull(quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_CANDIDATE_ROWS));
			assertNotNull(quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_STEP_LOOKUPS));
			assertNotNull(quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_EXPANSION_ITERATIONS));
			double candidates = quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_CANDIDATE_ROWS);
			double lookups = quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_STEP_LOOKUPS);
			double expansions = quantities.get(LmdbPropertyPathEstimator.PLANNED_PATH_EXPANSION_ITERATIONS);
			assertEquals(candidates, output.sequentialRows(), 0.0d);
			assertEquals(lookups, output.randomSeeks(), 0.0d);
			assertEquals(expansions, output.iteratorOpens(), 0.0d);
			assertEquals(expansions, output.pathExpansions(), 0.0d);
		} else {
			assertEquals(producer.getWorkRows(), output.workRows(), 0.0d);
		}
	}

	static BindingSetAssignment assignment(List<String> names, List<BindingSet> rows) {
		BindingSetAssignment result = new BindingSetAssignment();
		result.setBindingNames(Set.copyOf(names));
		result.setBindingSets(List.copyOf(rows));
		return result;
	}

	static StatementPattern pattern(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("predicate", predicate), Var.of(object));
	}

	static IRI start(int branch) {
		return VF.createIRI("urn:qualified-row:start:" + branch);
	}

	static IRI end(int branch) {
		return VF.createIRI("urn:qualified-row:end:" + branch);
	}

	enum Endpoint {
		START,
		END,
		BOTH
	}

