	static final class NativeSession {
		final PackedCostTestSupport.BinaryCostCall call;
		final PackedCostSession session;
		final LmdbPackedCostModel model;
		final LmdbEstimatorRuntime runtime;
		final DefaultEvaluationStrategy strategy;
		final Map<Integer, PackedCostEstimate> prices = new LinkedHashMap<>();

		NativeSession(PackedCostTestSupport.BinaryCostCall call, PackedCostSession session,
				LmdbPackedCostModel model, LmdbEstimatorRuntime runtime, DefaultEvaluationStrategy strategy) {
			this.call = call;
			this.session = session;
			this.model = model;
			this.runtime = runtime;
			this.strategy = strategy;
		}

		PackedCostEstimate leaf(int relation) {
			PackedCostEstimate output = new PackedCostEstimate();
			session.estimateLeaf(relation, call.emptyContext(), output);
			return remember(relation, output);
		}

		PackedCostEstimate pricePrefix(int relation) {
			PackedQueryView query = call.query();
			if (query.childCount(relation) == 0) {
				return leaf(relation);
			}
			PackedCostEstimate left = pricePrefix(query.childRelationId(relation, 0));
			PackedCostEstimate right = query.isInnerJoin(relation)
					? pricePrefix(query.childRelationId(relation, 1))
					: null;
			TupleExpr expression = query.materializeRelation(relation);
			double rows = count(expression);
			PackedCostEstimate output = new PackedCostEstimate();
			output.setContextualRows(rows, left.workRows() + (right == null ? 0.0d : right.workRows()) + rows);
			var context = call.operatorContext(left.outputRows(), right == null ? Double.NaN : right.outputRows(),
					left.evidenceStateId(), right == null ? 0 : right.evidenceStateId());
			if (right != null) {
				session.refineIntermediateJoin(context, output);
			}
			session.refineOperator(relation, context, output);
			return remember(relation, output);
		}

		JoinFactorCostModel.FactorCostEstimate producer(TupleExpr factor, Set<String> names, double rows,
				double unrelated) {
			var context = JoinFactorCostModel.CostContext.forOptimization(names, rows, Double.NaN, true, true,
					Map.of(), List.of()).withPrefixFactorsDescribeCurrentRows(false).withUnrelatedPrefixRows(unrelated);
			return runtime.factorCost(factor, context).orElseThrow();
		}

		long count(TupleExpr expression) {
			long count = 0L;
			try (var result = strategy.precompile(new QueryRoot(expression.clone()))
					.evaluate(EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					result.next();
					count++;
				}
			}
			return count;
		}

		PackedCostEstimate remember(int relation, PackedCostEstimate output) {
			PackedCostEstimate retained = new PackedCostEstimate();
			PackedCostTestSupport.copyCandidate(output, retained);
			prices.put(relation, retained);
			return output;
		}
	}
